#   project:     str-openings-01
#   rules:       R_STR_OPENING_ABOVE_V, R_STR_OPENING_BEAM_V, R_STR_OPENING_CLEARANCE_300_V, R_STR_OPENING_COLUMN_V
#   calculators: revit_category_intersection_count, revit_min_opening_clearance_mm, revit_openings_below_count
#   catalogue:   1303-15.1
#
# Inputs:  Run (bool), BoxFamilyFilter (str; ';'-separated parts of "Family Type", empty = every Generic Model instance)
# Outputs: Objects (DG class + Revit UniqueId per box, for OBJECT STATE Object), Geometry (box per box, for OBJECT STATE Geometry),
#          Labels, UniqueIds, RuleIds, Report, and for every property k: R<k> rule id, D<k> DataProperty IRI, P<k> values (one per box).
import math

import clr
clr.AddReference("RevitAPI")
clr.AddReference("RhinoInside.Revit")
clr.AddReference("DG.Core")
from System.Collections.Generic import List
from Autodesk.Revit import DB
from RhinoInside.Revit import Revit
import Rhino
import Rhino.Geometry as rg
import DG.Core.Mapping

FEET_TO_MM = 304.8
TOL_FT = 1.0 / FEET_TO_MM  # 1 mm
BOX_CLASS_IRI = "https://w3id.org/dg#OpeningBox"
BOX_CLASS_LABEL = "OpeningBox"
PROPERTIES = [
    {
        "calculator": "revit_openings_below_count",
        "dataPropertyIri": "https://w3id.org/dg#hasOpeningsBelowCount",
        "dataPropertyLabel": "hasOpeningsBelowCount",
        "key": "P1",
        "params": {
            "opening_categories": [
                "OST_Doors",
                "OST_Windows",
                "OST_SWallRectOpening"
            ]
        },
        "ruleId": "R_STR_OPENING_ABOVE_V"
    },
    {
        "calculator": "revit_category_intersection_count",
        "dataPropertyIri": "https://w3id.org/dg#hasBeamIntersectionCount",
        "dataPropertyLabel": "hasBeamIntersectionCount",
        "key": "P2",
        "params": {
            "categories": [
                "OST_StructuralFraming"
            ]
        },
        "ruleId": "R_STR_OPENING_BEAM_V"
    },
    {
        "calculator": "revit_min_opening_clearance_mm",
        "dataPropertyIri": "https://w3id.org/dg#hasMinOpeningClearanceMm",
        "dataPropertyLabel": "hasMinOpeningClearanceMm",
        "key": "P3",
        "params": {
            "opening_categories": [
                "OST_Doors",
                "OST_Windows",
                "OST_SWallRectOpening"
            ],
            "sentinel_mm": 100000
        },
        "ruleId": "R_STR_OPENING_CLEARANCE_300_V"
    },
    {
        "calculator": "revit_category_intersection_count",
        "dataPropertyIri": "https://w3id.org/dg#hasColumnIntersectionCount",
        "dataPropertyLabel": "hasColumnIntersectionCount",
        "key": "P4",
        "params": {
            "categories": [
                "OST_StructuralColumns",
                "OST_Columns"
            ]
        },
        "ruleId": "R_STR_OPENING_COLUMN_V"
    }
]


def _bic(name):
    return getattr(DB.BuiltInCategory, name)


def _category_filter(names):
    cats = List[DB.BuiltInCategory]()
    for name in names:
        cats.Add(_bic(name))
    return DB.ElementMulticategoryFilter(cats)


_OPTIONS = DB.Options()
_OPTIONS.ComputeReferences = False
_OPTIONS.DetailLevel = DB.ViewDetailLevel.Fine


def element_solids(element):
    solids = []

    def walk(geometry):
        for g in geometry:
            if isinstance(g, DB.Solid):
                if g.Volume > 1e-9:
                    solids.append(g)
            elif isinstance(g, DB.GeometryInstance):
                walk(g.GetInstanceGeometry())

    geometry = element.get_Geometry(_OPTIONS)
    if geometry is not None:
        walk(geometry)
    return solids


def bbox_corners(element):
    bb = element.get_BoundingBox(None)
    if bb is None:
        return []
    pts = []
    for x in (bb.Min.X, bb.Max.X):
        for y in (bb.Min.Y, bb.Max.Y):
            for z in (bb.Min.Z, bb.Max.Z):
                pts.append(bb.Transform.OfPoint(DB.XYZ(x, y, z)))
    return pts


class Context(object):
    """Model facts shared by every calculator; each fact is computed once per run."""

    def __init__(self, doc, boxes):
        self.doc = doc
        self.boxes = boxes
        self._solids = {}
        self._hits = {}
        self._walls = {}
        self._openings = {}

    def solids(self, box):
        key = box.Id.IntegerValue
        if key not in self._solids:
            self._solids[key] = element_solids(box)
        return self._solids[key]

    def intersecting(self, box, categories):
        key = (box.Id.IntegerValue, tuple(categories))
        if key in self._hits:
            return self._hits[key]
        found = {}
        solids = self.solids(box)
        if solids:
            for solid in solids:
                collector = (DB.FilteredElementCollector(self.doc)
                             .WherePasses(_category_filter(categories))
                             .WhereElementIsNotElementType()
                             .WherePasses(DB.ElementIntersectsSolidFilter(solid)))
                for e in collector:
                    if e.Id != box.Id:
                        found[e.Id.IntegerValue] = e
        else:
            bb = box.get_BoundingBox(None)
            if bb is not None:
                outline = DB.Outline(bb.Min, bb.Max)
                collector = (DB.FilteredElementCollector(self.doc)
                             .WherePasses(_category_filter(categories))
                             .WhereElementIsNotElementType()
                             .WherePasses(DB.BoundingBoxIntersectsFilter(outline, -TOL_FT)))
                for e in collector:
                    if e.Id != box.Id:
                        found[e.Id.IntegerValue] = e
        hits = [found[k] for k in sorted(found)]
        self._hits[key] = hits
        return hits

    def host_walls(self, box):
        return [w for w in self.intersecting(box, ["OST_Walls"]) if isinstance(w, DB.Wall)]

    def wall_frame(self, wall):
        curve = wall.Location.Curve if isinstance(wall.Location, DB.LocationCurve) else None
        if curve is None:
            return None
        p0 = curve.GetEndPoint(0)
        d = curve.GetEndPoint(1) - p0
        if d.GetLength() < 1e-9:
            return None
        return p0, d.Normalize()

    def rect_in_wall(self, element, frame):
        """(u0, u1, z0, z1) of the element's bounding box, in feet, in the wall plane."""
        p0, d = frame
        us = []
        zs = []
        for pt in bbox_corners(element):
            us.append((pt - p0).DotProduct(d))
            zs.append(pt.Z)
        if not us:
            return None
        return (min(us), max(us), min(zs), max(zs))

    def wall_openings(self, wall, categories):
        key = (wall.Id.IntegerValue, tuple(categories))
        if key in self._openings:
            return self._openings[key]
        wanted = set(int(_bic(c)) for c in categories)
        result = []
        for eid in wall.FindInserts(True, False, True, True):
            e = self.doc.GetElement(eid)
            if e is None or e.Category is None:
                continue
            if e.Category.Id.IntegerValue in wanted:
                result.append(e)
        result.sort(key=lambda e: e.Id.IntegerValue)
        self._openings[key] = result
        return result

    def box_and_openings_in_walls(self, box, categories):
        """[(box_rect, [opening_rect, ...])] for every wall the box intersects."""
        out = []
        for wall in self.host_walls(box):
            frame = self.wall_frame(wall)
            if frame is None:
                continue
            box_rect = self.rect_in_wall(box, frame)
            if box_rect is None:
                continue
            rects = []
            for opening in self.wall_openings(wall, categories):
                r = self.rect_in_wall(opening, frame)
                if r is not None:
                    rects.append(r)
            out.append((box_rect, rects))
        return out


def calc_category_intersection_count(ctx, box, params):
    """Elements of params["categories"] whose solid intersects the box solid."""
    return len(ctx.intersecting(box, list(params["categories"])))

def calc_min_opening_clearance_mm(ctx, box, params):
    """Minimal clear distance in the wall plane between the box and any opening of its host walls, in mm."""
    best = None
    for (u0, u1, z0, z1), rects in ctx.box_and_openings_in_walls(box, list(params["opening_categories"])):
        for (a0, a1, b0, b1) in rects:
            dx = max(0.0, a0 - u1, u0 - a1)
            dz = max(0.0, b0 - z1, z0 - b1)
            d = math.hypot(dx, dz) * FEET_TO_MM
            best = d if best is None else min(best, d)
    return float(params["sentinel_mm"]) if best is None else round(best, 1)

def calc_openings_below_count(ctx, box, params):
    """Openings in the box's host walls that overlap the box along the wall and end at or below its bottom."""
    count = 0
    for (u0, u1, z0, z1), rects in ctx.box_and_openings_in_walls(box, list(params["opening_categories"])):
        for (a0, a1, b0, b1) in rects:
            if min(u1, a1) - max(u0, a0) > TOL_FT and z0 >= b1 - TOL_FT:
                count += 1
    return count


CALCULATORS = {"revit_category_intersection_count": calc_category_intersection_count, "revit_min_opening_clearance_mm": calc_min_opening_clearance_mm, "revit_openings_below_count": calc_openings_below_count}


def collect_boxes(doc, family_filter):
    parts = [p.strip().lower() for p in (family_filter or "").split(";") if p.strip()]
    boxes = []
    collector = (DB.FilteredElementCollector(doc)
                 .OfCategory(DB.BuiltInCategory.OST_GenericModel)
                 .WhereElementIsNotElementType())
    for e in collector:
        if not isinstance(e, DB.FamilyInstance):
            continue
        name = (e.Symbol.Family.Name + " " + e.Symbol.Name).lower()
        if parts and not any(p in name for p in parts):
            continue
        boxes.append(e)
    boxes.sort(key=lambda e: e.UniqueId)
    return boxes


def box_geometry(box, scale):
    bb = box.get_BoundingBox(None)
    if bb is None:
        return None
    t = bb.Transform
    origin = rg.Point3d(t.Origin.X * scale, t.Origin.Y * scale, t.Origin.Z * scale)
    plane = rg.Plane(origin, rg.Vector3d(t.BasisX.X, t.BasisX.Y, t.BasisX.Z), rg.Vector3d(t.BasisY.X, t.BasisY.Y, t.BasisY.Z))
    box3 = rg.Box(plane,
                  rg.Interval(bb.Min.X * scale, bb.Max.X * scale),
                  rg.Interval(bb.Min.Y * scale, bb.Max.Y * scale),
                  rg.Interval(bb.Min.Z * scale, bb.Max.Z * scale))
    return box3.ToBrep()


def object_reference(unique_id):
    ref = DG.Core.Mapping.MappingObjectReference()
    t = ref.GetType()
    t.GetProperty("Iri").SetValue(ref, BOX_CLASS_IRI)
    t.GetProperty("Label").SetValue(ref, BOX_CLASS_LABEL)
    t.GetProperty("NativeId").SetValue(ref, unique_id)
    return ref


def run_calculator(doc, family_filter):
    boxes = collect_boxes(doc, family_filter)
    ctx = Context(doc, boxes)
    scale = Rhino.RhinoMath.UnitScale(Rhino.UnitSystem.Feet, Rhino.RhinoDoc.ActiveDoc.ModelUnitSystem)
    values = []
    errors = []
    for prop in PROPERTIES:
        fn = CALCULATORS[prop["calculator"]]
        column = []
        for box in boxes:
            try:
                column.append(fn(ctx, box, prop["params"]))
            except Exception as exc:  # reported, never silently dropped
                column.append(None)
                errors.append("%s %s: %s" % (prop["dataPropertyLabel"], box.UniqueId, exc))
        values.append(column)
    return boxes, values, errors, scale


Objects = []
Geometry = []
Labels = []
UniqueIds = []
RuleIds = []
for _p in PROPERTIES:
    if _p["ruleId"] not in RuleIds:
        RuleIds.append(_p["ruleId"])
Report = []
R1 = "R_STR_OPENING_ABOVE_V"
D1 = "https://w3id.org/dg#hasOpeningsBelowCount"
P1 = []
R2 = "R_STR_OPENING_BEAM_V"
D2 = "https://w3id.org/dg#hasBeamIntersectionCount"
P2 = []
R3 = "R_STR_OPENING_CLEARANCE_300_V"
D3 = "https://w3id.org/dg#hasMinOpeningClearanceMm"
P3 = []
R4 = "R_STR_OPENING_COLUMN_V"
D4 = "https://w3id.org/dg#hasColumnIntersectionCount"
P4 = []

if not Run:
    Report = ["Run = False: nothing computed"]
else:
    _doc = Revit.ActiveDBDocument
    if _doc is None:
        Report = ["No active Revit document"]
    else:
        _boxes, _values, _errors, _scale = run_calculator(_doc, BoxFamilyFilter)
        for _box in _boxes:
            Objects.append(object_reference(_box.UniqueId))
            Geometry.append(box_geometry(_box, _scale))
            Labels.append("%s : %s [%d]" % (_box.Symbol.Family.Name, _box.Symbol.Name, _box.Id.IntegerValue))
            UniqueIds.append(_box.UniqueId)
        P1 = _values[0]
        P2 = _values[1]
        P3 = _values[2]
        P4 = _values[3]
        Report = ["document: %s" % _doc.Title, "boxes: %d" % len(_boxes)]
        for _k, _prop in enumerate(PROPERTIES):
            _col = [v for v in _values[_k] if v is not None]
            Report.append("%s (%s): n=%d min=%s max=%s" % (
                _prop["dataPropertyLabel"], _prop["ruleId"], len(_col),
                min(_col) if _col else "-", max(_col) if _col else "-"))
        Report.extend(_errors)
